namespace CarRental.Application.Abstractions.Files;

/// <summary>
/// PORT: where uploaded files (inspection photos and documents) are kept. Implemented in
/// Infrastructure: a local folder in Development, Azure Blob Storage in production.
/// </summary>
/// <remarks>
/// The storage key is generated by the adapter (random, never the user's file name), so a file
/// name can never become a path. Files are only ever served through an authorised API endpoint,
/// never from a public static path. The Domain stores metadata only.
/// </remarks>
public interface IFileStorage
{
    /// <returns>The storage key to keep with the metadata.</returns>
    Task<string> SaveAsync(Stream content, string contentType, CancellationToken cancellationToken);

    /// <summary>Opens a stored file for reading. Throws FileNotFoundException-like errors as NotFoundException.</summary>
    Task<Stream> OpenReadAsync(string storageKey, CancellationToken cancellationToken);

    Task DeleteAsync(string storageKey, CancellationToken cancellationToken);
}
